import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View, useWindowDimensions } from 'react-native';
import Svg, {
  ClipPath, Defs, FeDropShadow, FeGaussianBlur, Filter, G, Image as SvgImage, LinearGradient, Path, RadialGradient, Stop,
} from 'react-native-svg';
import { BlurTargetView, BlurView } from 'expo-blur';
import { useRouter } from 'expo-router';
import { SCREENS } from '../screens';
import { IMAGES } from './assets';

/*
 * SketchScreen renders one Sketch artboard (generated by _tools/sketch2rn.py) at device width:
 *  - vector shapes, gradients, image fills, masks and drop shadows via react-native-svg
 *  - text as native <Text> using the design's fonts, sizes, colours, kerning and line heights
 *  - background blurs via expo-blur
 *  - tap hotspots that navigate between screens, and editable text fields
 */

const MONO = Platform.select({ ios: 'Menlo', android: 'monospace', default: 'monospace' });

function splitColor(c) {
  if (!c || typeof c !== 'string') return { color: c, opacity: 1 };
  if (c.length === 9) return { color: c.slice(0, 7), opacity: parseInt(c.slice(7), 16) / 255 };
  return { color: c, opacity: 1 };
}

function runStyle(r, s) {
  const st = { fontSize: r.sz * s, color: r.c };
  if (r.ff === 'system') {
    st.fontWeight = r.fw || '400';
    if (r.it) st.fontStyle = 'italic';
  } else if (r.ff === 'mono') {
    st.fontFamily = MONO;
    st.fontWeight = r.fw || '400';
  } else {
    st.fontFamily = r.ff;
  }
  if (r.ls) st.letterSpacing = r.ls * s;
  if (r.u) st.textDecorationLine = 'underline';
  if (r.st) st.textDecorationLine = 'line-through';
  return st;
}

function SvgLayer({ layer, screen, s, idp }) {
  const defs = [];
  let g = 0;
  const paint = (p) => {
    if (!p) return 'none';
    if (typeof p === 'string') return p;
    const id = `${idp}g${g++}`;
    const stops = p.s.map((st, i) => {
      const { color, opacity } = splitColor(st[1]);
      return <Stop key={i} offset={st[0]} stopColor={color} stopOpacity={opacity} />;
    });
    defs.push(p.g === 'r'
      ? <RadialGradient key={id} id={id} gradientUnits="userSpaceOnUse" cx={p.cx} cy={p.cy} r={p.r} fx={p.cx} fy={p.cy}>{stops}</RadialGradient>
      : <LinearGradient key={id} id={id} gradientUnits="userSpaceOnUse" x1={p.x1} y1={p.y1} x2={p.x2} y2={p.y2}>{stops}</LinearGradient>);
    return `url(#${id})`;
  };
  layer.cl.forEach((c) => {
    const cd = screen.clip[c];
    const eo = cd[0] === 'E';
    defs.push(<ClipPath key={`c${c}`} id={`${idp}c${c}`}><Path d={eo ? cd.slice(1) : cd} clipRule={eo ? 'evenodd' : 'nonzero'} /></ClipPath>);
  });
  const body = layer.svg.map((e, i) => {
    let node;
    if (e.k === 'p') {
      const fill = paint(e.f);
      const props = { d: e.d, fill, fillRule: e.eo ? 'evenodd' : 'nonzero' };
      if (e.o != null) props.opacity = e.o;
      if (e.s) {
        props.stroke = paint(e.s.p);
        props.strokeWidth = e.s.w;
        if (e.s.da) props.strokeDasharray = e.s.da;
        if (e.s.lc) props.strokeLinecap = e.s.lc;
        if (e.s.lj) props.strokeLinejoin = e.s.lj;
      }
      if (e.sh && e.sh.length) {
        const sh = e.sh[0];
        const fid = `${idp}f${i}`;
        const { color, opacity } = splitColor(sh.c);
        defs.push(
          <Filter key={fid} id={fid} filterUnits="userSpaceOnUse" x={-screen.w} y={-screen.h} width={screen.w * 3} height={screen.h * 3}>
            <FeDropShadow dx={sh.x} dy={sh.y} stdDeviation={sh.b / 2} floodColor={color} floodOpacity={opacity} />
          </Filter>,
        );
        props.filter = `url(#${fid})`;
      } else if (e.bl) {
        const fid = `${idp}f${i}`;
        defs.push(
          <Filter key={fid} id={fid} filterUnits="userSpaceOnUse" x={-screen.w} y={-screen.h} width={screen.w * 3} height={screen.h * 3}>
            <FeGaussianBlur stdDeviation={e.bl / 2} />
          </Filter>,
        );
        props.filter = `url(#${fid})`;
      }
      node = <Path key={i} {...props} />;
    } else {
      const par = e.fit === 'slice' ? 'xMidYMid slice' : e.fit === 'meet' ? 'xMidYMid meet' : 'none';
      node = (
        <SvgImage key={i} href={IMAGES[e.src]} x={e.x} y={e.y} width={e.w} height={e.h} preserveAspectRatio={par}
          opacity={e.o != null ? e.o : 1} transform={e.tf ? `matrix(${e.tf.join(' ')})` : undefined} />
      );
    }
    if (e.c) {
      for (let k = e.c.length - 1; k >= 0; k--) {
        node = <G key={`${i}-${k}`} clipPath={`url(#${idp}c${e.c[k]})`}>{node}</G>;
      }
    }
    return node;
  });
  return (
    <Svg style={StyleSheet.absoluteFill} width={screen.w * s} height={screen.h * s} viewBox={`0 0 ${screen.w} ${screen.h}`} pointerEvents="none">
      <Defs>{defs}</Defs>
      {body}
    </Svg>
  );
}

function TextLayer({ e, s }) {
  const [value, setValue] = useState('');
  const text = e.r.map((r) => r.s).join('');
  const lines = text.split('\n').length;
  const box = {
    position: 'absolute',
    left: e.tx * s,
    top: e.y * s,
    width: e.tw * s,
    lineHeight: e.lh * s,
    textAlign: e.al,
  };
  if (e.o != null) box.opacity = e.o;
  if (e.rot) {
    box.height = e.h * s; // rotate around the centre of the design's text box
    box.transform = [{ rotate: `${e.rot}deg` }];
  }
  if (e.in) {
    const st = runStyle(e.r[0], s);
    return (
      <TextInput
        value={value}
        onChangeText={setValue}
        placeholder={text}
        placeholderTextColor={e.r[0].c}
        secureTextEntry={e.in === 'password'}
        keyboardType={e.in === 'email' ? 'email-address' : e.in === 'number' ? 'number-pad' : 'default'}
        autoCapitalize="none"
        style={[box, st, { height: Math.max(e.h, e.lh) * s + 8 * s, top: (e.y - 4) * s, paddingVertical: 0, paddingHorizontal: 0, lineHeight: undefined }]}
      />
    );
  }
  const text_ = (
    <Text style={box} numberOfLines={e.auto ? lines : e.ml} ellipsizeMode="clip" pointerEvents="none" allowFontScaling={false}>
      {e.r.map((r, i) => <Text key={i} style={runStyle(r, s)}>{r.s}</Text>)}
    </Text>
  );
  if (!e.cb) return text_;
  // text clipped by a Sketch mask: wrap in a clipping box and offset the text inside it
  box.left -= e.cb[0] * s;
  box.top -= e.cb[1] * s;
  return (
    <View pointerEvents="none" style={{ position: 'absolute', left: e.cb[0] * s, top: e.cb[1] * s, width: e.cb[2] * s, height: e.cb[3] * s, overflow: 'hidden' }}>
      {text_}
    </View>
  );
}

function BlurLayer({ e, s, target }) {
  return (
    <BlurView
      intensity={Math.min(100, Math.round(e.br * 3))}
      tint="default"
      blurTarget={target}
      blurMethod="dimezisBlurView"
      pointerEvents="none"
      style={{ position: 'absolute', left: e.x * s, top: e.y * s, width: e.w * s, height: e.h * s, borderRadius: e.rad * s, overflow: 'hidden' }}
    />
  );
}

/** Renders layers; everything beneath a blur layer is wrapped in a BlurTargetView (needed on Android). */
function Layers({ layers, screen, s, slug, offset = 0 }) {
  const lastBlur = layers.map((l) => l.k === 'b').lastIndexOf(true);
  const target = useRef(null);
  const render = (L, i) => {
    const idx = i + offset;
    if (L.svg) return <SvgLayer key={idx} layer={L} screen={screen} s={s} idp={`${slug}-${idx}-`} />;
    if (L.k === 't') return <TextLayer key={idx} e={L} s={s} />;
    return null;
  };
  if (lastBlur < 0) return layers.map(render);
  return (
    <>
      <BlurTargetView ref={target} style={StyleSheet.absoluteFill} pointerEvents="box-none">
        <Layers layers={layers.slice(0, lastBlur)} screen={screen} s={s} slug={slug} offset={offset} />
      </BlurTargetView>
      <BlurLayer e={layers[lastBlur]} s={s} target={target} />
      {layers.slice(lastBlur + 1).map((L, i) => render(L, lastBlur + 1 + i))}
    </>
  );
}

export default function SketchScreen({ slug, drawer = false }) {
  const router = useRouter();
  const win = useWindowDimensions();
  const screen = useMemo(() => SCREENS[slug].load(), [slug]);
  // drawers keep the design's proportion to a phone (e.g. 260 of 375pt) and fill the height
  const width = drawer ? Math.min(win.width * 0.85, win.height * (screen.w / screen.h)) : win.width;
  const height = win.height;
  const s = width / screen.w;
  const contentH = screen.h * s;

  useEffect(() => {
    if (!screen.auto || !screen.auto.to) return undefined;
    // ?noauto (web) keeps splash-type screens still, e.g. for screenshots
    if (Platform.OS === 'web' && typeof window !== 'undefined' && window.location.search.includes('noauto')) return undefined;
    const t = setTimeout(() => router.replace(`/${screen.auto.to}`), screen.auto.ms);
    return () => clearTimeout(t);
  }, [screen, router]);

  const go = (h) => {
    if (h.to === 'back') {
      if (router.canGoBack()) router.back();
      return;
    }
    if (h.replace) router.replace(`/${h.to}`);
    else router.push(`/${h.to}`);
  };

  const canvas = (
    <View style={{ width, height: contentH, backgroundColor: screen.bg, overflow: 'hidden' }}>
      <Layers layers={screen.layers} screen={screen} s={s} slug={slug} />
      {screen.hs.map((h, i) => (
        <Pressable
          key={`hs${i}`}
          accessibilityRole="button"
          onPress={() => go(h)}
          style={({ pressed }) => ({
            position: 'absolute', left: h.r[0] * s, top: h.r[1] * s, width: h.r[2] * s, height: h.r[3] * s,
            backgroundColor: pressed ? 'rgba(127,127,127,0.12)' : 'transparent', borderRadius: 8 * s,
          })}
        />
      ))}
    </View>
  );

  if (drawer) {
    return (
      <View style={{ flex: 1, flexDirection: 'row' }}>
        <View style={{ width, height: contentH, backgroundColor: screen.bg }}>{canvas}</View>
        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.45)' }} onPress={() => router.canGoBack() && router.back()} />
      </View>
    );
  }
  return (
    <View style={{ flex: 1, backgroundColor: screen.bg }}>
      {contentH > height + 1 ? (
        <ScrollView bounces={false} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">{canvas}</ScrollView>
      ) : canvas}
    </View>
  );
}
